#!/usr/bin/env python3
"""Generate user_commands.s for the Neo Geo Media Centre sound driver.

Usage: python3 tools/gen_user_commands.py [MAX_TRACKS] > user_commands.s

Commands (written by the 68k to 0x320000):
  0..3          reserved by nullsound
  4             stop ADPCM-B
  5 + n         play track n
The track table (8 bytes per track, filled in by the Foundry) sits right
after the 12-byte marker "NGMC-ZTAB-01".
"""
import sys

n = int(sys.argv[1]) if len(sys.argv) > 1 else 64
out = []
w = out.append

w(""";;;
;;; Neo Geo Media Centre: z80 sound commands (generated by tools/gen_user_commands.py)
;;; Based on the ngdevkit ADPCM-B example, LGPL, Damien Ciabrini.
;;;
        .include "helpers.inc"
        .include "ym2610.inc"
        .area   CODE

;;; Jump table: commands 0-3 are reserved by nullsound.
;;; Command 4 stops ADPCM-B. Command 5+n plays track n.
cmd_jmptable::
        jp      snd_command_unused
        jp      snd_command_01_prepare_for_rom_switch
        jp      music_ngdevkit_eye_catcher
        jp      snd_command_03_reset_driver
        jp      stop_b""")
for i in range(n):
    w(f"        jp      play_{i:02d}")
w("        init_unused_cmd_jmptable\n")

w("""stop_b:
        call    snd_adpcm_b_stop
        ret

;;; ix points at an 8-byte entry:
;;;   start>>8 (lsb, msb), stop>>8 (lsb, msb), delta-n (lsb, msb), l/r, volume
play_common:
        call    snd_adpcm_b_play
        ret
""")
for i in range(n):
    w(f"play_{i:02d}:\n        ld      ix, #ngmc_track_table+{i*8}\n        jp      play_common")

w("""
;;; Track table, patched by the Foundry. Entries default to silence.
ngmc_ztab_magic:
        .ascii  "NGMC-ZTAB-01"
ngmc_track_table:""")
for i in range(n):
    w("        .db     0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xc0, 0xff")

print("\n".join(out))
